<template>
  <div>
    <div
        class="current-actual-block"
        style="
            background: url('https://cs12.pikabu.ru/post_img/big/2021/08/14/8/1628947545180348035.png') no-repeat;
            background-size: 100% auto;
            background-position: center;
      ">
      <template v-if="online === 'true'">
        <span class="active online-bulb"></span>
      </template>
      <span class="text-box">Стрим онлайн</span>
    </div>
  </div>
</template>

<script>
import $ from "jquery";

export default {
  name: 'CurrentActual',
  props: {
    online: {
      type: String,
      default: 'true'
    },
  },
  data: () => {
    return {
      element: document.querySelector('.online-bulb'),
    }
  },
  mounted() {
    let element = $('.online-bulb'),
        className = 'active';

    setInterval(
        function () {
          if (element.hasClass(className))
            element.removeClass(className);
          else
            element.addClass(className);
        },
        500
    );
  },
}
</script>

<style>
  .online-bulb {
    position: absolute;
    top: 30px;
    left: 30px;

    width: 50px;
    height: 50px;

    background: none;
    border-radius: 50px;

    transition: 1s;
  }

  .online-bulb.active {
    background: red;
  }

  .current-actual-block {
    position: relative;
    min-height: 400px;
    margin-left: -60px;
    margin-right: -60px;
  }

  .current-actual-block span.text-box {
    position: absolute;
    right: 0;
    bottom: 30px;
    background: var(--main-block-color);
    color: var(--second-text-color);
    padding: 10px 15px 10px 50px;
    font-size: 30px;
    text-transform: uppercase;
  }
</style>